"""Parser tests: dialect detection and the three format parsers."""

from firelint.parsers import detect_format, parse, parse_iptables, parse_nft, parse_ufw

IPTABLES = """\
# generated by iptables-save
*filter
:INPUT ACCEPT [0:0]
:FORWARD DROP [0:0]
:OUTPUT ACCEPT [0:0]
:MYCHAIN - [0:0]
-A INPUT -i lo -j ACCEPT
-A INPUT -p tcp -m tcp --dport 22 -j ACCEPT
-A INPUT -m conntrack --ctstate ESTABLISHED,RELATED -j ACCEPT
-A INPUT -p tcp -m comment --comment "temporary rule" --dport 8080 -s 10.0.0.0/8 -j ACCEPT
-A INPUT --dport
-A MYCHAIN -p udp --sport 53 -j RETURN
COMMIT
*nat
:PREROUTING ACCEPT [0:0]
-A PREROUTING -p tcp --dport 80 -j DNAT --to-destination 10.0.0.5:8080
COMMIT
"""

NFT = """\
table inet filter {
	chain input {
		type filter hook input priority filter; policy drop;
		iif "lo" accept
		ct state established,related counter accept
		tcp dport { 22, 8080 } ip saddr 10.0.0.0/8 accept
		log prefix "dropped: " drop
	}
}

table ip6 nat {
	chain prerouting {
		type nat hook prerouting priority dstnat;
		tcp dport 80 dnat to [fd00::5]:8080
	}
}
"""

UFW = """\
Status: active

Logging: on (low)
Default: deny (incoming), allow (outgoing), disabled (routed)
New profiles: skip

To                         Action      From
--                         ------      ----
22/tcp                     ALLOW IN    10.0.0.0/8
443                        ALLOW IN    Anywhere
53/udp                     DENY IN     Anywhere (v6)
Anywhere                   ALLOW OUT   Anywhere
"""


def test_detect_ufw():
    assert detect_format(UFW) == "ufw"


def test_detect_iptables():
    assert detect_format(IPTABLES) == "iptables"


def test_detect_nft():
    assert detect_format(NFT) == "nft"


def test_detect_unknown():
    assert detect_format("hello world\njust some prose\n") is None


def test_detect_by_filename_fallback():
    assert detect_format("-A INPUT -j ACCEPT\n", "rules.v4") == "iptables"


def test_iptables_chains_and_policies():
    target = parse_iptables(IPTABLES, "rules.v4")
    chains = {c.name: c for c in target.chains if c.table == "filter"}
    assert chains["INPUT"].policy == "ACCEPT"
    assert chains["FORWARD"].policy == "DROP"
    assert chains["MYCHAIN"].policy == ""
    assert chains["MYCHAIN"].policy_stated is False
    assert chains["INPUT"].hooked and chains["MYCHAIN"].hooked is False


def test_iptables_rule_fields():
    target = parse_iptables(IPTABLES, "rules.v4")
    rules = target.rules
    ssh = next(r for r in rules if r.dport == "22")
    assert ssh.action == "ACCEPT" and ssh.proto == "tcp" and ssh.chain == "INPUT"
    established = next(r for r in rules if r.stateful)
    assert established.action == "ACCEPT"
    scoped = next(r for r in rules if r.dport == "8080")
    assert scoped.src == "10.0.0.0/8" and scoped.comment == "temporary rule"


def test_iptables_any_source_normalized():
    target = parse_iptables("*filter\n:INPUT ACCEPT [0:0]\n-A INPUT -s 0.0.0.0/0 -j ACCEPT\nCOMMIT\n", "x")
    assert target.rules[0].src == "any"


def test_iptables_malformed_line_warned():
    target = parse_iptables(IPTABLES, "rules.v4")
    assert any("--dport" in raw for _line, _offset, raw in target.warnings)


def test_iptables_comment_lines_skipped():
    target = parse_iptables(IPTABLES, "rules.v4")
    assert not any("#" in raw for _line, _offset, raw in target.warnings)


def test_iptables_dnat_target():
    target = parse_iptables(IPTABLES, "rules.v4")
    nat = next(r for r in target.rules if r.action == "DNAT")
    assert nat.nat_to == "10.0.0.5:8080" and nat.table == "nat"


def test_nft_chain_header():
    target = parse_nft(NFT, "ruleset.nft")
    chains = {c.name: c for c in target.chains}
    assert chains["INPUT"].hooked is True
    assert chains["INPUT"].policy == "DROP" and chains["INPUT"].policy_stated is True
    assert chains["PREROUTING"].policy_stated is False


def test_nft_rule_fields():
    target = parse_nft(NFT, "ruleset.nft")
    input_rules = [r for r in target.rules if r.chain == "INPUT"]
    port_rule = next(r for r in input_rules if r.dport)
    assert port_rule.dport == "22,8080" and port_rule.src == "10.0.0.0/8"
    established = next(r for r in input_rules if r.stateful)
    assert established.action == "ACCEPT"
    logged = next(r for r in input_rules if r.action == "DROP")
    assert "log prefix" in logged.raw


def test_nft_inline_set_ports_match():
    target = parse_nft(NFT, "ruleset.nft")
    port_rule = next(r for r in target.rules if r.dport == "22,8080")
    assert port_rule.dport_matches("8080") and port_rule.dport_matches("22")
    assert not port_rule.dport_matches("443")


def test_nft_dnat_and_ipv6():
    target = parse_nft(NFT, "ruleset.nft")
    nat = next(r for r in target.rules if r.action == "DNAT")
    assert nat.nat_to == "[fd00::5]:8080" and nat.ipv6 is True


def test_nft_families_cover_ipv6():
    target = parse_nft(NFT, "ruleset.nft")
    assert target.meta["covers_ipv6"] is True


def test_nft_ip_only_no_ipv6():
    target = parse_nft("table ip filter {\n\tchain input {\n\t\ttype filter hook input priority 0;\n\t}\n}\n", "x")
    assert target.meta["covers_ipv6"] is False


def test_ufw_meta():
    target = parse_ufw(UFW, "ufw.txt")
    assert target.meta["status"] == "active"
    assert target.meta["logging"] == "on"
    chains = {c.name: c for c in target.chains}
    assert chains["INPUT"].policy == "DROP"
    assert chains["OUTPUT"].policy == "ACCEPT"
    assert chains["FORWARD"].policy == "DROP"


def test_ufw_rows():
    target = parse_ufw(UFW, "ufw.txt")
    rules = target.rules
    ssh = next(r for r in rules if r.dport == "22")
    assert ssh.action == "ACCEPT" and ssh.proto == "tcp" and ssh.src == "10.0.0.0/8" and ssh.chain == "INPUT"
    wide = next(r for r in rules if r.dport == "443")
    assert wide.proto == "" and wide.src == "any"
    denied = next(r for r in rules if r.action == "DROP")
    assert denied.ipv6 is True and denied.proto == "udp"
    out = next(r for r in rules if r.chain == "OUTPUT")
    assert out.action == "ACCEPT" and out.src == "any"


def test_ufw_inactive_status():
    target = parse_ufw("Status: inactive\n\nTo Action From\n-- ------ ----\n22/tcp ALLOW IN Anywhere\n", "u")
    assert target.meta["status"] == "inactive"


def test_parse_dispatch_unknown():
    target = parse("nothing recognizable here\n", "x.txt")
    assert target.fmt == "unknown"
    assert len(target.warnings) == 1
